contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint ticketAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (ticketAmount)); require(ticketAmount <= 1000000000000000000000000000000);
        require(ticketAmount == 10, "ticket amount must be 10");
        require(address(this).balance >= ticketAmount, "insufficient balance");

        uint bankBefore = c.bank().balance;
        uint contractBefore = address(c).balance;
        uint potBefore = c.pot(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.play{value: ticketAmount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint bankAfter = c.bank().balance;
        uint contractAfter = address(c).balance;
        uint potAfter = c.pot(); if (__ESBMC_reverted()) return;

        assert(
            reverted
            || (potAfter == 0 && bankAfter == bankBefore && contractAfter == contractBefore)
            || (potAfter == potBefore + ticketAmount && bankAfter > bankBefore && contractAfter == contractBefore + ticketAmount)
        );
    }

    receive() external payable {}
}

