pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EtherLotto c;

    function setUp() public {
        c = new EtherLotto();
    }

    function _run(uint256 ticketAmount) internal {
        ticketAmount = bound(ticketAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        ticketAmount = 10;
        vm.assume(address(this).balance >= ticketAmount);
        uint bankBefore = c.bank().balance;
        uint contractBefore = address(c).balance;
        uint256 potBefore;
        try c.pot() returns (uint256 __r) { potBefore = __r; } catch { return; }
        bool reverted;
        try c.play{value: ticketAmount}() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint bankAfter = c.bank().balance;
        uint contractAfter = address(c).balance;
        uint256 potAfter;
        try c.pot() returns (uint256 __r) { potAfter = __r; } catch { return; }
        assertTrue(reverted
            || (potAfter == 0 && bankAfter == bankBefore && contractAfter == contractBefore)
            || (potAfter == potBefore + ticketAmount && bankAfter > bankBefore && contractAfter == contractBefore + ticketAmount));
    }

    function testFuzz_run(uint256 ticketAmount) public {
        _run(ticketAmount);
    }

    receive() external payable {}
}
